export interface Order {
  items: number;
  subtotal: number;
  shipping: number;
}

function discountRate(count: number): number {
  if (count >= 50) return 0.15;
  if (count >= 10) return 0.05;
  return 0;
}

export function total(order: Order): number {
  const rate = discountRate(order.items);
  const discounted = order.subtotal * (1 - rate);
  return Math.round((discounted + order.shipping) * 100) / 100;
}

export function chunk<T>(items: readonly T[], size: number): T[][] {
  const out: T[][] = [];
  for (let i = 0; i < items.length; i += size) out.push(items.slice(i, i + size));
  return out;
}

export function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

